    CONSTRAINT volume_publisher_is_not_blank CHECK (((publisher = btrim(publisher)) AND (publisher <> ''::text))),
    CONSTRAINT volume_series_number_is_positive CHECK (((series_number IS NULL) OR (series_number > 0))),
    CONSTRAINT volume_title_is_not_blank CHECK (((title = btrim(title)) AND (title <> ''::text)))
);


--
-- Name: TABLE volume; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.volume IS 'One object as catalogued: publisher, edition line, Binding, language, ISBN — everything about the *thing* and nothing about the narrative. Being catalogued is not being owned (ADR-0007): whether it is in the house is an acquisition. There is deliberately no medium column, so an owned ebook is not a row this table can hold.';


--
-- Name: COLUMN volume.edition_line; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.volume.edition_line IS 'The publisher''s line, not the volume itself.';


--
-- Name: COLUMN volume.language; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.volume.language IS 'A language code — it, en, ja.';


--
-- Name: COLUMN volume.series_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.volume.series_id IS 'The Series this object belongs to, where it belongs to one.';


--
-- Name: COLUMN volume.series_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.volume.series_number IS 'Its position in that Series: 12 of Slam Dunk.';


--
-- Name: volume_story; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.volume_story (
    volume_id uuid NOT NULL,
    story_id uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: TABLE volume_story; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.volume_story IS 'Which Stories a Volume carries: many-to-many in both directions (ADR-0001). One Volume holds several Stories and one Story spans several Volumes, and neither side is derived from the other — the link is stored.';


--
-- Name: wish; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.wish (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    volume_id uuid NOT NULL,
    priority integer NOT NULL,
    target_price numeric(10,2),
    price_found numeric(10,2),
    shop text,
    opened_on date DEFAULT CURRENT_DATE NOT NULL,
    closed_on date,
    CONSTRAINT wish_close_follows_open CHECK (((closed_on IS NULL) OR (closed_on >= opened_on))),
    CONSTRAINT wish_price_found_is_not_negative CHECK (((price_found IS NULL) OR (price_found >= (0)::numeric))),
    CONSTRAINT wish_priority_is_one_to_three CHECK (((priority >= 1) AND (priority <= 3))),
    CONSTRAINT wish_shop_is_not_blank CHECK (((shop IS NULL) OR ((shop = btrim(shop)) AND (shop <> ''::text)))),
    CONSTRAINT wish_target_price_is_not_negative CHECK (((target_price IS NULL) OR (target_price >= (0)::numeric)))
);


--
-- Name: TABLE wish; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.wish IS 'An open intention to acquire a named Volume. There is deliberately no state column: a fulfilled Wish is a Wish that ended, so the end is a day and `Acquistato` is not representable. Nothing but the close verb writes closed_on.';


--
-- Name: COLUMN wish.priority; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wish.priority IS 'Which to buy first: 1 next, 2 soon, 3 someday.';


--
-- Name: COLUMN wish.closed_on; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.wish.closed_on IS 'Null is an open Wish, and the shopping list. A day is a Wish the owner ended.';


